import { useNavigate } from 'react-router-dom';
import { History, Trash2, Copy, Pencil, Eye } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Card } from '@/components/ui/Card';
import { Badge } from '@/components/ui/Badge';
import { usePromptStore } from '@/lib/store/promptStore';
import { useWizardStore } from '@/lib/store/wizardStore';
import { copyToClipboard } from '@/lib/utils/clipboard';
import type { ComposedPrompt } from '@/types/prompt.types';
import type { UseCaseId } from '@/types/knowledge.types';
import { useLanguage } from '@/components/layout/LanguageProvider';

export default function HistoryPage() {
  const navigate = useNavigate();
  const { lang, t } = useLanguage();
  const { history, clearHistory, removeFromHistory, setCurrent } = usePromptStore();

  const handleView = (p: ComposedPrompt) => {
    // نمرّر البرومبت عبر location.state بدل setCurrent المباشر
    // لأن WizardPage سيمسح current عند الدخول
    navigate(`/create/${p.meta.mode}`, {
      state: { promptToView: p },
    });
  };

  const handleEdit = (p: ComposedPrompt) => {
    if (!p.answers) {
      // البرومبتات القديمة (قبل التحديث) ليس عندها answers محفوظة
      alert(
        'هذا البرومبت قديم ولا يحتوي على الإجابات الأصلية.\n' +
        'يمكنك عرضه أو نسخه، أو توليد برومبت جديد بنفس الإعدادات.',
      );
      return;
    }

    const { resetContext, setAnswers, setStep } = useWizardStore.getState();
    // امسح السياق السابق أولاً ثم املأ من البرومبت
    resetContext();
    setAnswers({ ...p.answers, mode: p.meta.mode as UseCaseId });
    setStep(0);

    navigate(`/create/${p.meta.mode}`, {
      state: { skipReset: true },
    });
  };

  const handleCopy = async (p: ComposedPrompt) => {
    await copyToClipboard(p.prompts[0]);
  };

  if (history.length === 0) {
    return (
      <div className="mx-auto max-w-4xl px-4 py-16 sm:px-6">
        <div className="flex flex-col items-center gap-4 text-center">
          <History size={64} className="text-text-muted" />
          <h1 className="text-2xl font-bold text-text-primary">{t('history.emptyTitle')}</h1>
          <p className="text-text-secondary">
            {t('history.emptyDescription')}
          </p>
          <Button onClick={() => navigate('/create')}>{t('home.ctaCreate')}</Button>
        </div>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-5xl px-4 py-10 sm:px-6">
      <div className="mb-6 flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gradient">{t('history.title')}</h1>
          <p className="text-sm text-text-secondary">
            {t('history.subtitle', { count: history.length })}
          </p>
        </div>
        <Button variant="danger" size="sm" onClick={clearHistory}>
          <Trash2 size={14} /> {t('common.clearAll')}
        </Button>
      </div>

      <div className="space-y-3">
        {history.map((p) => (
          <Card
            key={p.id}
            padding="md"
            className="transition-colors hover:border-primary/30"
          >
            <div className="flex items-start justify-between gap-3">
              <div className="flex-1 min-w-0">
                <div className="mb-2 flex flex-wrap items-center gap-2">
                  <Badge color="#8B5CF6">{t(`modes.${p.meta.mode}.title`)}</Badge>
                  <Badge>{t(`wizard.settings.${p.meta.lengthMode}`)}</Badge>
                  {p.meta.strategy && <Badge color="#06B6D4">{t(`strategies.${p.meta.strategy}`)}</Badge>}
                  {p.meta.usedProfile && (
                    <Badge color="#10B981">{t('history.profile')}</Badge>
                  )}
                  <span className="text-xs text-text-muted">
                    {new Date(p.meta.generatedAt).toLocaleString(lang === 'ar' ? 'ar-EG' : 'en-US')}
                  </span>
                </div>
                <p className="line-clamp-2 text-sm text-text-secondary" dir="auto">
                  {p.prompts[0]?.slice(0, 160)}...
                </p>
                <p className="mt-1 text-xs text-text-muted">
                  {t('history.promptStats', {
                    terms: p.meta.selectedTermIds.length.toLocaleString(lang === 'ar' ? 'ar-EG' : 'en-US'),
                    chars: p.meta.totalChars.toLocaleString(lang === 'ar' ? 'ar-EG' : 'en-US'),
                  })}
                </p>
              </div>

              <div className="flex flex-col gap-1">
                <Button size="sm" variant="primary" onClick={() => handleView(p)}>
                  <Eye size={12} /> {t('common.view')}
                </Button>
                <Button size="sm" variant="secondary" onClick={() => handleEdit(p)}>
                  <Pencil size={12} /> {t('common.edit')}
                </Button>
                <div className="flex gap-1">
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => handleCopy(p)}
                    title={t('common.copy')}
                  >
                    <Copy size={12} />
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => removeFromHistory(p.id)}
                    title={t('common.delete')}
                  >
                    <Trash2 size={12} />
                  </Button>
                </div>
              </div>
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}